/// # Errors
/// Returns an error if the write operation fails.
///
/// This function returns a `Result` type that contains an error if the write operation fails.
///
/// # Examples
///
/// ```
/// let container = TestOpenFgaContainer::new();
/// let result = container.allow_wildcard(Permission::Read, ResourceRef::new(",user:alice"))?.await;
/// ```

pub async fn write_tuple(
    &self,
    user: &str,
    relation: &str,
    object: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let body = json!({
        "writes": {
            "tuple_keys": [{
                "user": user,
                "relation": relation,
                "object": object,
            }]
        },
        "authorization_model_id": self.authorization_model_id,
    });

    let url = format!(
        "{}/stores/{}/write",
        self.base_url,
        self.store_id
    );
    let response = self.client.post(&url).json(&body).send().await?;
    let status = response.status();

    if !status.is_success() {
        let text = response.text().await.unwrap_or_default();

        // Idempotent writes: OpenFGA rejects duplicates with
        // `cannot_write_tuple_which_already_exists`. Treat as success
        // so per-test arrange code can be re-run safely.
        if text.contains(
            "cannot_write_tuple_which_already_exists"
        ) || text.contains(
            "write_failed_due_to_invalid_input"
        ) && text.contains(
            "already exists"
        ) {
            debug!(
                user,
                relation,
                object,
                "OpenFGA write tolerated duplicate tuple"
            );
            return Ok(());
        }

        return Err(format!(
            "OpenFGA write returned {status} for ({user}, {relation}, {object}): {text}"
        ).into());
    }

    Ok(())
}

